Set-Location "c:/git/semio/elements/lib/board"; $script = @'
import { chromium } from "playwright";
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
await page.goto("http://127.0.0.1:6029/", { waitUntil: "load", timeout: 180000 });
await page.getByTestId("board-play-fixture-shelf").waitFor({ state: "visible", timeout: 120000 });
const canvases = page.locator("[data-testid='board-canvas']");
await canvases.first().waitFor({ state: "visible", timeout: 120000 });
const count = await canvases.count();
const beforeZoom = await canvases.evaluateAll((els) => els.map((el) => el.getAttribute("data-board-zoom")));
const beforeCamera = await canvases.evaluateAll((els) => els.map((el) => el.getAttribute("data-board-camera")));
const target = canvases.nth(1);
const box = await target.boundingBox();
if (!box) throw new Error("no box");
const cx = box.x + box.width / 2;
const cy = box.y + box.height / 2;
await page.mouse.move(cx, cy);
await page.mouse.wheel(0, -600);
await page.waitForTimeout(300);
const afterWheelZoom = await canvases.evaluateAll((els) => els.map((el) => el.getAttribute("data-board-zoom")));
const afterWheelCamera = await canvases.evaluateAll((els) => els.map((el) => el.getAttribute("data-board-camera")));
await page.mouse.move(cx, cy);
await page.mouse.down({ button: "middle" });
await page.mouse.move(cx + 80, cy + 40);
await page.mouse.up({ button: "middle" });
await page.waitForTimeout(300);
const afterPanZoom = await canvases.evaluateAll((els) => els.map((el) => el.getAttribute("data-board-zoom")));
const afterPanCamera = await canvases.evaluateAll((els) => els.map((el) => el.getAttribute("data-board-camera")));
console.log(JSON.stringify({ count, beforeZoom, beforeCamera, afterWheelZoom, afterWheelCamera, afterPanZoom, afterPanCamera }, null, 2));
await browser.close();
'@; bun -e $script

